events.message:
Executing command: run Verify seven educational data-source links, const items = [
  {id:'nasa-open-apis', title:'NASA Open APIs', purpose:'Source entry in ARES-7 v3; drives optional DONKI synchronization.'},
  {id:'donki', title:'NASA DONKI', purpose:'Source entry in ARES-7 v3; supplies solar flare records.'},
  {id:'curiosity-rad', title:'Curiosity RAD / RadLab', purpose:'Source entry in ARES-7 v3; radiation reference at Gale Crater.'},
  {id:'osdr', title:'NASA OSDR', purpose:'Source entry in ARES-7 v3; home page for display-only biomarkers when no study is verified.'},
  {id:'mars-trek', title:'Mars Trek', purpose:'Source entry in ARES-7 v3; landing-site coordinates and elevations.'},
  {id:'csa-food', title:'CSA Food Production', purpose:'ARES-7 v3 names “Food production on the moon and in remote areas”; drives the crop and food-loop learning card.'},
  {id:'csa-youth', title:'CSA STEM and youth', purpose:'ARES-7 v3 names “Space resources for STEM and youth organizations”; drives junior STEM tip/reflection material.'}
]
const schema = {type:'object',additionalProperties:false,properties:{resourceId:{type:'string'},title:{type:'string'},url:{type:'string'},verified:{type:'boolean'},evidence:{type:'string'},scopeNote:{type:'string'}},required:['resourceId','title','url','verified','evidence','scopeNote']}
const mapped = await parallel('Verify seven educational data-source links', () => items.map(item => agent(
  'Verify exactly one official source entry: ' + item.title + '. Purpose: ' + item.purpose + '\nSearch the web for the canonical official source, open/fetch the resulting official URL (do not rely on snippets), and determine whether it resolves and supports that purpose. Return resourceId="' + item.id + '", its accurate title, the canonical direct URL (or empty string if unavailable), verified=true only if the official page was actually opened and clearly relevant, short evidence including what the page says and the fetch/open result, and a scopeNote. Do not invent page contents, quotes, IDs or studies. If only a home page can be verified, return it and say so.',
  {brief:'Verify official ' + item.title + ' source link',schema,sandbox:'isolated',effort_level:'lite'}
)), {schema})
return {items: mapped.map((result,index) => result.ok ? result.value : {resourceId:items[index].id,title:items[index].title,url:'',verified:false,evidence:result.error.message,scopeNote:'Unverified; omit detailed claim.'})}

